/**
 * CH-05 — Construcción del presupuesto HTML
 * Modo: Run Once for Each Item
 *
 * Fuente oficial de datos:
 * $('Normalizar salida IA').item.json
 */

// ---------------------------------------------------------
// 1. Recuperar datos originales
// ---------------------------------------------------------

const datos = $('Normalizar salida IA').item.json;

if (!datos || typeof datos !== 'object') {
  throw new Error(
    'No se pudieron recuperar los datos desde "Normalizar salida IA".'
  );
}

// ---------------------------------------------------------
// 2. Validar campos obligatorios
// ---------------------------------------------------------

const camposObligatorios = [
  'concepto',
  'periodo_desde',
  'periodo_hasta',
  'importe',
  'moneda',
  'email_destinatario',
  'presupuesto_id',
  'fecha_solicitud',
];

const camposAusentes = camposObligatorios.filter((campo) => {
  const valor = datos[campo];

  return (
    valor === undefined ||
    valor === null ||
    (typeof valor === 'string' && valor.trim() === '')
  );
});

if (camposAusentes.length > 0) {
  throw new Error(
    `No se puede construir el presupuesto. Faltan campos: ${camposAusentes.join(', ')}`
  );
}

const importe = Number(datos.importe);

if (!Number.isFinite(importe) || importe <= 0) {
  throw new Error(
    `El importe recibido no es válido: ${String(datos.importe)}`
  );
}

// ---------------------------------------------------------
// 3. Funciones auxiliares
// ---------------------------------------------------------

/**
 * Escapa contenido dinámico para evitar que caracteres como
 * &, <, >, " y ' rompan el documento HTML.
 */
function escaparHtml(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

/**
 * Convierte una fecha válida a formato argentino.
 * Si no puede interpretarse, conserva el valor original escapado.
 */
function formatearFecha(valor) {
  const fecha = new Date(valor);

  if (Number.isNaN(fecha.getTime())) {
    return escaparHtml(valor);
  }

  return new Intl.DateTimeFormat('es-AR', {
    timeZone: 'America/Argentina/Salta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(fecha);
}

/**
 * Formatea el importe con separador de miles y coma decimal.
 *
 * Ejemplos:
 * 150000       → 150.000,00
 * 1500000.50   → 1.500.000,50
 */
function formatearImporte(valor) {
  return new Intl.NumberFormat('es-AR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(valor);
}

/**
 * Sanitiza el identificador para utilizarlo dentro del nombre del archivo.
 */
function sanitizarNombreArchivo(valor) {
  const limpio = String(valor ?? '')
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .replace(/_+/g, '_');

  if (!limpio) {
    throw new Error(
      'No se pudo generar un nombre de archivo válido.'
    );
  }

  return limpio;
}

// ---------------------------------------------------------
// 4. Preparar valores dinámicos
// ---------------------------------------------------------

const presupuestoId = escaparHtml(datos.presupuesto_id);
const fechaPresupuesto = formatearFecha(datos.fecha_solicitud);
const concepto = escaparHtml(datos.concepto);
const periodoDesde = escaparHtml(datos.periodo_desde);
const periodoHasta = escaparHtml(datos.periodo_hasta);
const moneda = escaparHtml(datos.moneda);
const emailDestinatario = escaparHtml(datos.email_destinatario);

const importeFormateado = formatearImporte(importe);
const importeCompleto = `${moneda} ${importeFormateado}`;

const presupuestoIdArchivo = sanitizarNombreArchivo(
  datos.presupuesto_id
);

const nombreArchivo =
  `Presupuesto_${presupuestoIdArchivo}.pdf`;

// ---------------------------------------------------------
// 5. Construir HTML
// ---------------------------------------------------------

const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">

  <meta
    name="viewport"
    content="width=device-width, initial-scale=1.0"
  >

  <title>Presupuesto ${presupuestoId}</title>

  <style>
    @page {
      size: A4 portrait;
      margin: 14mm;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      padding: 0;
      background: #ffffff;
      color: #1f2933;
      font-family: Arial, Helvetica, sans-serif;
      font-size: 11pt;
      line-height: 1.4;
    }

    body {
      width: 100%;
    }

    .documento {
      min-height: 267mm;
      display: flex;
      flex-direction: column;
      border: 1px solid #d7dde3;
      padding: 13mm;
    }

    .encabezado {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 18mm;
      padding-bottom: 8mm;
      border-bottom: 2px solid #25364a;
    }

    .institucion {
      flex: 1;
    }

    .institucion-nombre {
      margin: 0 0 2mm;
      font-size: 16pt;
      font-weight: 700;
      color: #25364a;
    }

    .institucion-detalle {
      margin: 0;
      color: #586572;
      font-size: 9.5pt;
    }

    .titulo-contenedor {
      min-width: 68mm;
      text-align: right;
    }

    .titulo {
      margin: 0 0 3mm;
      font-size: 22pt;
      letter-spacing: 1px;
      color: #25364a;
    }

    .referencia {
      margin: 1mm 0;
      color: #465564;
      font-size: 9.5pt;
    }

    .referencia strong {
      color: #1f2933;
    }

    .seccion {
      margin-top: 9mm;
    }

    .seccion-titulo {
      margin: 0 0 4mm;
      padding-bottom: 2mm;
      border-bottom: 1px solid #d7dde3;
      color: #25364a;
      font-size: 11pt;
      text-transform: uppercase;
      letter-spacing: 0.6px;
    }

    .fila {
      display: flex;
      margin-bottom: 3mm;
    }

    .etiqueta {
      width: 37mm;
      flex-shrink: 0;
      font-weight: 700;
      color: #465564;
    }

    .valor {
      flex: 1;
      overflow-wrap: anywhere;
    }

    .concepto {
      min-height: 24mm;
      padding: 5mm;
      border: 1px solid #d7dde3;
      background: #f7f9fb;
      border-radius: 3px;
    }

    .importe {
      margin-top: 7mm;
      padding: 6mm;
      border: 2px solid #25364a;
      text-align: center;
      background: #f7f9fb;
    }

    .importe-etiqueta {
      margin-bottom: 2mm;
      color: #586572;
      font-size: 9.5pt;
      text-transform: uppercase;
      letter-spacing: 0.8px;
    }

    .importe-valor {
      color: #25364a;
      font-size: 22pt;
      font-weight: 700;
    }

    .condiciones {
      margin: 0;
      padding-left: 5mm;
    }

    .condiciones li {
      margin-bottom: 2mm;
    }

    .observacion {
      margin-top: 5mm;
      padding: 4mm;
      border-left: 3px solid #7a8794;
      background: #f7f9fb;
      color: #465564;
      font-size: 9.5pt;
    }

    .pie {
      margin-top: auto;
      padding-top: 12mm;
    }

    .firma {
      width: 70mm;
      margin-left: auto;
      text-align: center;
    }

    .firma-linea {
      margin-bottom: 2mm;
      border-top: 1px solid #1f2933;
    }

    .firma-texto {
      color: #586572;
      font-size: 9pt;
    }

    .nota-final {
      margin-top: 8mm;
      padding-top: 4mm;
      border-top: 1px solid #d7dde3;
      color: #6a7681;
      font-size: 8.5pt;
      text-align: center;
    }
  </style>
</head>

<body>
  <main class="documento">

    <header class="encabezado">
      <section class="institucion">
        <h2 class="institucion-nombre">
          Servicios Patagónicos S.R.L.
        </h2>

        <p class="institucion-detalle">
          Servicios de logística y traslado de personal
        </p>

        <p class="institucion-detalle">
          Neuquén, República Argentina
        </p>
      </section>

      <section class="titulo-contenedor">
        <h1 class="titulo">PRESUPUESTO</h1>

        <p class="referencia">
          <strong>Número:</strong>
          ${presupuestoId}
        </p>

        <p class="referencia">
          <strong>Fecha:</strong>
          ${fechaPresupuesto}
        </p>
      </section>
    </header>

    <section class="seccion">
      <h3 class="seccion-titulo">Destinatario</h3>

      <div class="fila">
        <div class="etiqueta">Correo:</div>

        <div class="valor">
          ${emailDestinatario}
        </div>
      </div>
    </section>

    <section class="seccion">
      <h3 class="seccion-titulo">Detalle del servicio</h3>

      <div class="concepto">
        ${concepto}
      </div>

      <div class="fila" style="margin-top: 5mm;">
        <div class="etiqueta">Período:</div>

        <div class="valor">
          ${periodoDesde} a ${periodoHasta}
        </div>
      </div>

      <div class="importe">
        <div class="importe-etiqueta">
          Importe total presupuestado
        </div>

        <div class="importe-valor">
          ${importeCompleto}
        </div>
      </div>
    </section>

    <section class="seccion">
      <h3 class="seccion-titulo">Condiciones</h3>

      <ul class="condiciones">
        <li>
          El importe corresponde exclusivamente al servicio
          detallado en este documento.
        </li>

        <li>
          Cualquier modificación del alcance deberá ser evaluada
          y presupuestada nuevamente.
        </li>

        <li>
          La coordinación operativa estará sujeta a disponibilidad
          y confirmación previa.
        </li>
      </ul>

      <div class="observacion">
        Este presupuesto tiene una validez de 15 días corridos
        desde su fecha de emisión.
      </div>
    </section>

    <footer class="pie">
      <div class="firma">
        <div class="firma-linea"></div>

        <div class="firma-texto">
          Servicios Patagónicos S.R.L.<br>
          Identificación institucional
        </div>
      </div>

      <div class="nota-final">
        Documento generado automáticamente.
        Su emisión no implica aceptación hasta su confirmación formal.
      </div>
    </footer>

  </main>
</body>
</html>`;

// ---------------------------------------------------------
// 6. Salida del nodo
// ---------------------------------------------------------

return {
  json: {
    html,
    nombre_archivo: nombreArchivo,
    email_destinatario: String(datos.email_destinatario),
    presupuesto_id: String(datos.presupuesto_id),

    fecha_formateada: fechaPresupuesto,
    periodo_formateado:
      `${datos.periodo_desde} a ${datos.periodo_hasta}`,
    importe_formateado: importeCompleto,
  },

  binary: {
    html_file: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
      fileExtension: 'html',
    },
  },
};

const item = $input.item;

if (!item.binary?.data) {
  throw new Error(
    'No se encontró el archivo PDF en la propiedad binaria "data".'
  );
}

const nombreArchivo =
  $('HTML - Construir Presupuesto').item.json.nombre_archivo;

if (!nombreArchivo) {
  throw new Error(
    'No se pudo recuperar el nombre dinámico del presupuesto.'
  );
}

return {
  json: item.json,
  binary: {
    ...item.binary,
    data: {
      ...item.binary.data,
      fileName: nombreArchivo,
      fileExtension: 'pdf',
      mimeType: 'application/pdf',
    },
  },
};
